def _run_docker_turn(self, prompt: str, turn_index: int) -> None:
    if self.provider in {"pi", "claude-code", "hermes"}:
        self._write_prompt_file(prompt)
    command, stdin_text = self._turn_command(turn_index)
    if self.provider == "codex":
        stdin_text = prompt
    stdout_lines, stderr_text = self._stream_process(command, stdin_text)
